func diff(curResults, preResults models.ScanResults, plus, minus bool) (diffed models.ScanResults, err error) {
	for _, current := range curResults {
		found := false
		var previous models.ScanResult
		for _, r := range preResults {
			if current.ServerName == r.ServerName && current.Container.Name == r.Container.Name {
				found = true
				previous = r
				break
			}
		}

		if found {
			current.ScannedCves = getDiffCves(previous, current, plus, minus)
			packages := models.Packages{}
			for _, s := range current.ScannedCves {
				for _, affected := range s.AffectedPackages {
					if s.DiffStatus == models.DiffMinus {
						if p, ok := previous.Packages[affected.Name]; ok {
							packages[affected.Name] = p
						}
					} else if p, ok := current.Packages[affected.Name]; ok {
						packages[affected.Name] = p
					}
				}
			}
			current.Packages = packages
		} else {
			original := current.ScannedCves
			current.ScannedCves = models.VulnInfos{}
			if plus {
				for id, v := range original {
					v.DiffStatus = models.DiffPlus
					current.ScannedCves[id] = v
				}
			}
		}

		diffed = append(diffed, current)
	}
	return diffed, err
}

func getDiffCves(previous, current models.ScanResult, plus, minus bool) models.VulnInfos {
	changed := models.VulnInfos{}
	if plus {
		for id, v := range current.ScannedCves {
			if _, exists := previous.ScannedCves[id]; !exists {
				v.DiffStatus = models.DiffPlus
				changed[id] = v
			}
		}
	}
	if minus {
		for id, v := range previous.ScannedCves {
			if _, exists := current.ScannedCves[id]; !exists {
				v.DiffStatus = models.DiffMinus
				changed[id] = v
			}
		}
	}
	return changed
}

func isCveFixed(current models.VulnInfo, previous models.ScanResult) bool {
	preVinfo, _ := previous.ScannedCves[current.CveID]
	pre := map[string]bool{}
	for _, h := range preVinfo.AffectedPackages {
		pre[h.Name] = h.NotFixedYet
	}

	cur := map[string]bool{}
	for _, h := range current.AffectedPackages {
		cur[h.Name] = h.NotFixedYet
	}

	return !reflect.DeepEqual(pre, cur)
}
